import { $, driver, expect } from '@wdio/globals';
import { byText, byTextContains, byTextMatches, byLabel, byLabelStartsWith, allByText, scrollToText, swipeUp, tapText } from '../../helpers/ui.ts';
import { toHome } from '../../helpers/app.ts';
import { shown } from './app-0710.ts';
import {
  openAdminHome, scrollToMatch, cardRe, setField, tapLowest, pickInAndroidPicker,
  REC_CARD, REC_UPLOAD_BTN, REC_REMOVE_BTN, REC_NONE,
} from './admin.ts';

type AnyEl = ReturnType<typeof byText> | WebdriverIO.Element;
export type Rect = { x: number; y: number; width: number; height: number };

/** Прямоугольник элемента (iOS — точки, Android — пиксели; те же единицы, что у getWindowSize). */
export async function rectOf(el: AnyEl): Promise<Rect> {
  const e = (await el) as WebdriverIO.Element;
  const { x, y } = await e.getLocation();
  const { width, height } = (await e.getSize()) as { width: number; height: number };
  return { x, y, width, height };
}

/** Точный текст именно у текстового элемента (не у склеенной подписи контейнера). */
export function staticText(text: string) {
  return driver.isAndroid
    ? $(`android=new UiSelector().text("${text}")`)
    : $(`-ios predicate string:type == "XCUIElementTypeStaticText" AND label == "${text}"`);
}

/** Высота строки статуса: iOS — mobile: deviceScreenInfo (точки), Android — getSystemBars (пиксели). Нет данных — 0. */
export async function statusBarHeight(): Promise<number> {
  try {
    if (driver.isIOS) {
      const info = (await driver.execute('mobile: deviceScreenInfo')) as { statusBarSize?: { height?: number } };
      return Number(info?.statusBarSize?.height ?? 0);
    }
    const bars = (await driver.getSystemBars()) as unknown as { statusBar?: { height?: number } };
    return Number(bars?.statusBar?.height ?? 0);
  } catch { return 0; }
}

/** Прокрутить вниз, пока элемент (по фабрике) не станет видимым. */
export async function scrollToEl(get: () => AnyEl, what: string, max = 10) {
  for (let i = 0; i <= max; i++) {
    const el = (await get()) as WebdriverIO.Element;
    if (await el.isDisplayed().catch(() => false)) return el;
    await swipeUp();
  }
  throw new Error(`Не найден элемент после прокрутки: ${what}`);
}

/** Выравнивание текста по рамке элемента: 'right' — правая половина экрана, 'left' — левая,
 *  'unknown' — рамка почти на всю ширину (позиция букв внутри рамки не видна → @manual-check). */
export async function sideOf(el: AnyEl): Promise<'right' | 'left' | 'unknown'> {
  const { width } = await driver.getWindowSize();
  const r = await rectOf(el);
  if (r.width >= width * 0.8) return 'unknown';
  const cx = r.x + r.width / 2;
  return cx > width / 2 ? 'right' : 'left';
}

// ───────────────────────── системное окно «Поделиться» ─────────────────────────

/** Открыто ли системное окно шаринга (iOS share sheet / Android chooser). TODO калибровка: подписи действий на устройстве (he/ru/en). */
export async function shareSheetShown(): Promise<boolean> {
  const el = driver.isIOS
    ? await $('-ios predicate string:name == "ActivityListView" OR (type == "XCUIElementTypeCell" AND label IN {"Copy","העתקה","העתק","Скопировать"})')
    : await $('android=new UiSelector().resourceIdMatches(".*(chooser|resolver|sharesheet).*")');
  return el.isExisting().catch(() => false);
}

export async function waitShareSheet(timeout = 15000) {
  await driver.waitUntil(shareSheetShown, { timeout, interval: 500, timeoutMsg: 'системное окно «Поделиться» не открылось' });
}

/** Закрыть системное окно шаринга БЕЗ отправки: iOS — свайп вниз за верх окна, Android — «назад». */
export async function dismissShareSheet() {
  for (let attempt = 0; attempt < 3 && (await shareSheetShown()); attempt++) {
    if (driver.isAndroid) {
      await driver.back();
    } else {
      const { width, height } = await driver.getWindowSize();
      const sheet = await $('-ios predicate string:name == "ActivityListView"');
      const top = (await sheet.isExisting().catch(() => false)) ? (await rectOf(sheet)).y : Math.round(height * 0.45);
      await driver.action('pointer', { parameters: { pointerType: 'touch' } })
        .move({ x: Math.round(width / 2), y: Math.max(1, Math.round(top + 12)) })
        .down().pause(80)
        .move({ duration: 350, x: Math.round(width / 2), y: Math.round(height * 0.97) })
        .up().perform();
      if (attempt === 2) {
        const close = await $('-ios predicate string:type == "XCUIElementTypeButton" AND label IN {"Close","Закрыть","סגור"}');
        if (await close.isExisting().catch(() => false)) await close.click().catch(() => {});
      }
    }
    await driver.pause(800);
  }
  expect(await shareSheetShown()).toBe(false);
}

/** Предпросмотр своего окна шаринга (#cc02d264, F-95 AC4): пояснение, «ביטול», «המשך לשיתוף». */
export const SHARE_PREVIEW = 'זו ההודעה שתישלח, בלי שום פרט נוסף:';
export async function expectSharePreview(message?: string) {
  await expect(byTextContains(SHARE_PREVIEW)).toBeDisplayed({ wait: 15000 });
  if (message) await expect(byTextContains(message)).toBeDisplayed();
  await expect(byText('ביטול')).toBeDisplayed();
  await expect(byText('המשך לשיתוף')).toBeDisplayed();
}

// ───────────────────────── нижние вкладки ─────────────────────────

/** Вкладки без «תפילות» (экран падает в сборке 19 — баг #70e8283a). */
export const SAFE_TABS = ['בית', 'תהילים', 'המסע שלי', 'ברכות'] as const;
/** Признак экрана вкладки (подтверждены 07–13.10). TODO калибровка: для «המסע שלי» — признак «דרגה N מתוך M» (HM-01). */
const TAB_MARKER: Record<string, () => ReturnType<typeof byText>> = {
  'בית': () => byLabel('התחל תפילה'),
  'תהילים': () => byText('פרקי אבות'),
  'המסע שלי': () => byTextMatches('.*דרגה \\d+ מתוך \\d+.*'),
  'ברכות': () => byTextContains('הברכות מוצגות בנוסח'),
};

/** Нажать вкладку (самый нижний элемент с этим текстом — нижняя навигация) и дождаться её экрана. */
export async function switchTabAndCheck(tab: string) {
  await tapLowest(tab);
  await driver.waitUntil(async () => {
    if (await shown(TAB_MARKER[tab]())) return true;
    // запасной признак — вкладка помечена выбранной (accessibilityState.selected)
    for (const el of await allByText(tab)) {
      if ((await el.getAttribute(driver.isAndroid ? 'selected' : 'selected').catch(() => null)) === 'true') return true;
    }
    return false;
  }, { timeout: 15000, interval: 600, timeoutMsg: `вкладка «${tab}» не переключилась` });
}

/** После закрытия окон шаринга нижние вкладки переключаются (#cc02d264, #403c0b3d). */
export async function expectTabsSwitch() {
  for (const tab of SAFE_TABS) await switchTabAndCheck(tab);
  await switchTabAndCheck('בית');
}

// ───────────────────────── «המסע שלי» → «מפת השפעה» ─────────────────────────

/** Счётчик карты «N אנשים» (#403c0b3d, F-95 AC3: шаринг не меняет карту). */
export async function impactMapCount(): Promise<string> {
  await toHome();
  await switchTabAndCheck('המסע שלי');
  const w = await byTextContains('עלית דרגה');
  if (await w.waitForDisplayed({ timeout: 1500 }).then(() => true, () => false)) await tapText('סגירה');
  await scrollToText('מפת השפעה');
  const el = await scrollToMatch('.*\\d+ אנשים.*', 6);
  const t = (await el.getText()) || (await el.getAttribute(driver.isAndroid ? 'content-desc' : 'label')) || '';
  const m = t.match(/\d+ אנשים/);
  if (!m) throw new Error(`Счётчик «N אנשים» не разобран: ${t}`);
  return m[0];
}

// ───────────────────────── админка: «בורא פרי העץ · נוסח אשכנז» ─────────────────────────

export const HAETZ_SECTION_PREFIX = '1, בורא פרי העץ';
export const NO_DRAFTS = 'כל הקטעים מאושרים ואין טיוטות ממתינות.';

/** Профиль → «ממשק ניהול התוכן: מנהל תוכן…» → «בורא פרי העץ · נוסח אשכנז…» (экран молитвы в админке). */
export async function openAdminHaetz() {
  await openAdminHome();
  await (await scrollToMatch(`(?s).*${cardRe('בורא פרי העץ', 'אשכנז')}.*`)).click();
  await scrollToEl(() => byLabelStartsWith(HAETZ_SECTION_PREFIX), `«${HAETZ_SECTION_PREFIX}…»`);
}

/** … → «1, בורא פרי העץ…» → «עריכת קטע». */
export async function openAdminHaetzSection() {
  await openAdminHaetz();
  await (await byLabelStartsWith(HAETZ_SECTION_PREFIX)).click();
  await (await byText('עריכת קטע')).waitForDisplayed({ timeout: 20000 });
}

/** Выйти из «עריכת קטע» БЕЗ сохранения. TODO калибровка: подпись кнопки «назад» в шапке (iOS 13.10 — круглая «חזרה»). */
export async function leaveEditWithoutSaving() {
  for (const lbl of ['חזרה', 'חזור', 'Back']) {
    const b = await byLabel(lbl);
    if (await b.isDisplayed().catch(() => false)) { await b.click(); break; }
  }
  if (await shown(byText('עריכת קטע'))) await driver.back().catch(() => {});
  // Если появится окно «изменения не сохранены» — выбрать выход без сохранения (TODO калибровка текста кнопки).
  for (const t of ['יציאה בלי שמירה', 'צא בלי לשמור', 'יציאה']) {
    const b = await byText(t);
    if (await b.isDisplayed().catch(() => false)) { await b.click(); break; }
  }
  await driver.waitUntil(async () => !(await shown(byText('עריכת קטע'))), { timeout: 15000, timeoutMsg: 'не вышли из «עריכת קטע»' });
}

// ───────────────────────── загрузка MP3 в приложении (F-92, 13.10) ─────────────────────────

export const REC_NEED_RECORDER = 'יש לכתוב מי הקליט לפני ההעלאה.';
export const REC_UPLOADED = (file: string) => `הקובץ ${file} הועלה. ההקראה תוצע למשתמשים רק אחרי אישור.`;
export const REC_PENDING_FULL = 'ממתינה לאישור — המשתמשים עדיין לא שומעים אותה.';
export const REC_BROKEN = 'הקובץ שנבחר אינו קובץ שמע תקין, ולכן לא נטען. העלו קובץ MP3 אחר.';
export const REC_NONE_PREFIX = 'לקטע הזה אין עדיין הקראה';

/**
 * Системный выбор файла. Android — DocumentsUI (файл заранее положен pushToDownloads).
 * iOS — «Файлы»: вкладка «Недавние» → файл (файлы должны лежать на телефоне в «Файлы»; Appium их туда не кладёт).
 * Если файл не нашёлся за 15 с — выбрать вручную (@manual-check): вызывающий тест ждёт результат загрузки до 3 минут.
 * TODO калибровка: подписи вкладки «Недавние» и имени файла (iOS показывает имя без расширения).
 * ОБНОВЛЕНО 25.10: возвращает true, если файл выбран автоматически. `opts.labelPrefix` — начало label ячейки iOS
 * (факт 25.10: ячейка «arvit-ashk-k3 2, mp3, …» во «Недавние»/«Recents» — копия файла с суффиксом « 2»);
 * `opts.cancelIfMissing` — не найден → закрыть выбор файла («Отменить»/«Cancel»/«ביטול») и вернуть false (вызывающий тест делает skip).
 */
export async function pickFileInSystemPicker(fileName: string, opts: { labelPrefix?: string; cancelIfMissing?: boolean } = {}): Promise<boolean> {
  if (driver.isAndroid) { await pickInAndroidPicker(fileName); return true; }
  const base = opts.labelPrefix ?? fileName.replace(/\.mp3$/i, '');
  for (const t of ['Недавние', 'Recents', 'אחרונים']) {
    const tab = await $(`-ios predicate string:type == "XCUIElementTypeButton" AND label == "${t}"`);
    if (await tab.isExisting().catch(() => false)) { await tab.click().catch(() => {}); break; }
  }
  const file = await $(`-ios predicate string:(label BEGINSWITH "${base}" OR name BEGINSWITH "${base}") AND type != "XCUIElementTypeStaticText"`);
  if (await file.waitForExist({ timeout: 15000 }).then(() => true, () => false)) {
    await file.click();
    for (const t of ['Открыть', 'Open', 'פתיחה', 'פתח']) {
      const b = await $(`-ios predicate string:type == "XCUIElementTypeButton" AND label == "${t}"`);
      if (await b.isExisting().catch(() => false)) { await b.click().catch(() => {}); break; }
    }
    return true;
  }
  if (opts.cancelIfMissing) {
    for (const t of ['Отменить', 'Cancel', 'ביטול']) {
      const b = await $(`-ios predicate string:type == "XCUIElementTypeButton" AND label == "${t}"`);
      if (await b.isExisting().catch(() => false)) { await b.click().catch(() => {}); break; }
    }
    console.log(`[app-e2e] файл «${base}…» не найден в «Недавние» — положите его в «Файлы» на телефоне`);
    return false;
  }
  console.log(`[app-e2e] @manual-check: выберите на телефоне файл «${fileName}» (Файлы → Недавние). Тест ждёт до 3 минут…`);
  return false;
}

/** На экране «עריכת קטע»: «מי הקליט» → «העלאת קובץ MP3» → системный выбор файла. true — файл выбран автоматически. */
export async function uploadRecordingAny(fileName: string, recordedBy: string, opts: { labelPrefix?: string; cancelIfMissing?: boolean } = {}): Promise<boolean> {
  await scrollToText(REC_CARD);
  await setField('מי הקליט', recordedBy);
  await (await scrollToText(REC_UPLOAD_BTN)).click();
  return pickFileInSystemPicker(fileName, opts);
}

/** «הסרת ההקראה» → окно «להסיר את ההקראה?» → «הסרת ההקראה» (кнопка окна — верхняя из двух одинаковых) → «ההקראה הוסרה.». Нет записи → false. */
export async function removeRecordingWithDialog(): Promise<boolean> {
  await scrollToText(REC_CARD);
  if (!(await shown(byText(REC_REMOVE_BTN)))) await scrollToText(REC_REMOVE_BTN, 4).catch(() => {});
  if (!(await shown(byText(REC_REMOVE_BTN)))) return false;
  await (await byText(REC_REMOVE_BTN)).click();
  await (await byText('להסיר את ההקראה?')).waitForDisplayed({ timeout: 10000 });
  let best: WebdriverIO.Element | undefined, bestY = Infinity;
  for (const el of await allByText(REC_REMOVE_BTN)) {
    if (!(await el.isDisplayed().catch(() => false))) continue;
    const { y } = await el.getLocation();
    if (y < bestY) { bestY = y; best = el; }
  }
  if (!best) throw new Error('В окне «להסיר את ההקראה?» нет кнопки «הסרת ההקראה»');
  await best.click();
  await expect(byTextContains('ההקראה הוסרה.')).toBeDisplayed({ wait: 20000 });
  await expect(byTextContains(REC_NONE)).toBeDisplayed();
  return true;
}
